function mean(a){ return a.reduce(function(s,x){return s+x;},0)/a.length; }
function covariance(x, y){ if(x.length!==y.length||x.length<2) return NaN; var mx=mean(x), my=mean(y); var s=0; for(var i=0;i<x.length;i++) s+=(x[i]-mx)*(y[i]-my); return s/(x.length-1); }
function pearson(x, y){ if(x.length!==y.length||x.length<2) return NaN; var sx=covariance(x,x), sy=covariance(y,y); if(sx<=0||sy<=0) return NaN; return covariance(x,y)/Math.sqrt(sx*sy); }
var EXPORTS = { pearson:pearson, covariance:covariance, mean:mean };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CorrelationForgePure = EXPORTS; }
